}

fn tag(h: &mut Harness, tags: Value) -> Value {
    h.run(json!({"Command": "TagQueue", "QueueName": "q", "Tags": tags}))
}

fn tags(h: &mut Harness) -> Value {
    h.ok(json!({"Command": "ListQueueTags", "QueueName": "q"}))["Tags"].clone()
}

#[test]
fn new_queue_has_no_tags_and_tags_replace_and_add() {
    let mut h = setup();
    assert_eq!(tags(&mut h), json!({}));
    assert_eq!(tag(&mut h, json!({"a": "1", "b": ""})), json!({"ok": true}));
    assert_eq!(tag(&mut h, json!({"a": "2", "c": "3"})), json!({"ok": true}));
    assert_eq!(tags(&mut h), json!({"a": "2", "b": "", "c": "3"}));
    assert_eq!(tag(&mut h, json!({})), json!({"ok": true}));
}

#[test]
fn keys_are_case_sensitive() {
    let mut h = setup();
    tag(&mut h, json!({"k": "1", "K": "2"}));
    assert_eq!(tags(&mut h), json!({"k": "1", "K": "2"}));
}

#[test]
fn invalid_keys_and_values() {
    let mut h = setup();
    let long_key = "k".repeat(129);
    let ok_key = "k".repeat(128);
    for bad in [
        json!({"": "v"}),
        json!({"a b": "v"}),
        json!({long_key: "v"}),
        json!({"a": 1}),
        json!({"a": null}),
        json!({"ok": "fine", "a": "x".repeat(257)}),
        json!({"a": "é".repeat(129)}),
    ] {
        let r = tag(&mut h, bad.clone());
        assert_eq!(r["error"]["code"], "InvalidParameterValue", "{bad}");
    }
    assert_eq!(tags(&mut h), json!({}), "failed commands change nothing");
    assert_eq!(tag(&mut h, json!({ok_key: "é".repeat(128)}))["ok"], true);
}

#[test]
fn parameter_errors_follow_the_check_order() {
    let mut h = setup();
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "q"})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "TagQueue", "Tags": {}})), "MissingParameter");
    assert_eq!(
        h.err(json!({"Command": "TagQueue", "QueueName": "q", "Tags": []})),
        "InvalidParameterValue"
    );
    assert_eq!(
        h.err(json!({"Command": "TagQueue", "QueueName": "nope", "Tags": {"a": 1}})),
        "InvalidParameterValue"
    );
    assert_eq!(
        h.err(json!({"Command": "TagQueue", "QueueName": "nope", "Tags": {}})),
        "QueueDoesNotExist"
    );
    assert_eq!(h.err(json!({"Command": "UntagQueue", "QueueName": "q"})), "MissingParameter");
    assert_eq!(
        h.err(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": {}})),
        "InvalidParameterValue"
    );
    assert_eq!(
        h.err(json!({"Command": "ListQueueTags", "QueueName": "nope"})),
        "QueueDoesNotExist"
    );
}

#[test]
fn at_most_fifty_tags() {
    let mut h = setup();
    let many = |range: std::ops::Range<u32>| -> Value {
        range.map(|i| (format!("k{i}"), json!("v"))).collect::<serde_json::Map<_, _>>().into()
    };
    assert_eq!(tag(&mut h, many(0..51))["error"]["code"], "LimitExceeded");
    assert_eq!(tags(&mut h), json!({}));
    assert_eq!(tag(&mut h, many(0..50))["ok"], true);
    // replacing existing keys does not add to the count
    assert_eq!(tag(&mut h, json!({"k0": "new", "k49": "new"}))["ok"], true);
    // one new key too many fails the whole command, even with valid replacements
    assert_eq!(
        tag(&mut h, json!({"k0": "newer", "extra": "x"}))["error"]["code"],
        "LimitExceeded"
    );
    assert_eq!(tags(&mut h)["k0"], "new");
    // a freed slot can be used
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["k1"]}));
    assert_eq!(tag(&mut h, json!({"extra": "x"}))["ok"], true);
}

#[test]
fn untag_removes_listed_keys_and_ignores_unknown_ones() {
    let mut h = setup();
    tag(&mut h, json!({"a": "1", "b": "2"}));
    assert_eq!(
        h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["a", "zzz"]})),
        json!({"ok": true})
    );
    assert_eq!(tags(&mut h), json!({"b": "2"}));
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": []}));
    assert_eq!(tags(&mut h), json!({"b": "2"}));
    for bad in [json!([1]), json!(["a b"]), json!(["a", ""]), json!([null])] {
        assert_eq!(
            h.err(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": bad})),
            "InvalidParameterValue"
        );
    }
    assert_eq!(tags(&mut h), json!({"b": "2"}));
}

#[test]
fn tags_are_not_attributes_and_survive_purge_but_not_delete() {
    let mut h = setup();
    tag(&mut h, json!({"a": "1"}));
    let r = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert!(r["Attributes"].get("Tags").is_none());
    // CreateQueue rule 4 ignores tags: same attributes means success
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    assert_eq!(tags(&mut h), json!({"a": "1"}));
    h.ok(json!({"Command": "SendMessage", "QueueName": "q", "Body": "x"}));
    h.ok(json!({"Command": "PurgeQueue", "QueueName": "q"}));
    assert_eq!(tags(&mut h), json!({"a": "1"}));
    h.ok(json!({"Command": "DeleteQueue", "QueueName": "q"}));
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    assert_eq!(tags(&mut h), json!({}));
}
